+            "59 59 23 31 12 ? 2099",
+            repo,
+            null,
+            null));
+        assertTrue(highLevelClient().indexLifecycle().
+            putSnapshotLifecyclePolicy(request, RequestOptions.DEFAULT)
+            .isAcknowledged());
+    }
